const tabId = 1962625065;
const url = "https://www.microcenter.com/search/search_results.aspx?fq=category:External+Hard+Drives|514,Platform:Mac&sortby=pricelow&myStore=false&rpp=96";
await tool.navigate({ tabId, url });
await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 15000 });

const pageData = await browserjs(tabId, () => {
  const products = Array.from(document.querySelectorAll('.product_wrapper, article.product, li.product_wrapper')).map(p => {
    const titleEl = p.querySelector('a.productClickItemV2[href*="/product/"]:not(.image2)') || p.querySelector('.p-title, h2, a[data-name]');
    const title = titleEl ? (titleEl.getAttribute('data-name') || titleEl.textContent.trim()) : null;
    const href = titleEl?.href;
    const priceEl = p.querySelector('.price, [itemprop="price"], .p-price');
    const priceText = priceEl?.innerText.trim();
    // Parse price number
    const match = priceText?.match(/\$([0-9,]+\.[0-9]{2})/);
    const price = match ? parseFloat(match[1].replace(/,/g, '')) : null;
    const sku = p.querySelector('.sku')?.textContent.trim() || p.innerText.match(/SKU:\s*(\d+)/)?.[1];

    return { title, priceText, price, sku, href };
  }).filter(p => p.title && p.price !== null);

  return {
    url: window.location.href,
    totalFound: products.length,
    products
  };
});

console.log(`Found ${pageData.totalFound} products.`);
