const allCards = await browserjs(tabId, () => {
  const cards = Array.from(document.querySelectorAll('.product_wrapper, article.product, li.product_wrapper'));
  return cards.map((p, idx) => {
    // Title
    const titleEl = p.querySelector('a.productClickItemV2[href*="/product/"]:not(.image2)') || p.querySelector('.p-title, h2, a[data-name]');
    const dataName = titleEl?.getAttribute('data-name');
    const textTitle = titleEl?.textContent.trim();
    const title = dataName || textTitle || "No title found";

    // Price
    const priceEl = p.querySelector('.price, [itemprop="price"], .p-price');
    const priceText = priceEl?.innerText.trim();
    const match = priceText?.match(/\$([0-9,]+\.[0-9]{2})/);
    const price = match ? parseFloat(match[1].replace(/,/g, '')) : null;

    // Sku
    const sku = p.innerText.match(/SKU:\s*(\d+)/)?.[1] || "";

    // In store / shippable
    const stock = p.querySelector('.stock, .inventory')?.innerText.trim() || "";

    return {
      index: idx + 1,
      title,
      price,
      priceText,
      sku,
      stock
    };
  });
});
