const tabId = 1962625065;
const productsData = await browserjs(tabId, () => {
  const cards = Array.from(document.querySelectorAll('.product_wrapper, article.product, li.product_wrapper'));

  return cards.map((p, idx) => {
    // Title
    const titleLink = p.querySelector('a.productClickItemV2[href*="/product/"]:not(.image2)') || p.querySelector('.p-title, h2, a[data-name]');
    const rawTitle = titleLink?.getAttribute('data-name') || titleLink?.textContent.trim() || "";
    // Clean up html entities like &quot;
    const title = rawTitle.replace(/&quot;/g, '"').replace(/&amp;/g, '&');

    // Brand
    const brand = titleLink?.getAttribute('data-brand') || "";

    // Price
    const priceEl = p.querySelector('.price, [itemprop="price"], .p-price');
    const priceText = priceEl?.innerText.trim() || "";
    const favLink = p.querySelector('a.favorite');
    const dataPrice = favLink?.getAttribute('data-price');

    // Parse numeric price
    const match = priceText.match(/\$([0-9,]+\.[0-9]{2})/);
    const parsedPrice = match ? parseFloat(match[1].replace(/,/g, '')) : (dataPrice ? parseFloat(dataPrice) : null);

    // SKU
    const sku = p.innerText.match(/SKU:\s*(\d+)/)?.[1] || "";

    // Stock / availability
    const inStoreOnly = p.innerText.includes("In Store Only");
    const pickupOnly = p.innerText.includes("AVAILABLE FOR IN-STORE PICKUP ONLY");

    // Rating
    const ratingEl = p.querySelector('.bv_text, [aria-label*="stars"]');
    const rating = ratingEl?.textContent.trim() || "";

    // Original price / savings
    const originalPriceMatch = p.innerText.match(/Original price\s*\$([0-9,]+\.[0-9]{2})/);
    const originalPrice = originalPriceMatch ? originalPriceMatch[1] : null;

    return {
      rank: idx + 1,
      brand,
      title,
      price: parsedPrice,
      displayPrice: match ? `$${match[1]}` : (dataPrice ? `$${dataPrice} (unlisted in search card)` : "Price not listed"),
      originalPrice: originalPrice ? `$${originalPrice}` : null,
      sku,
      rating,
      availability: inStoreOnly ? "In Store Only" : "Available"
    };
  });
});

console.log(`Extracted ${productsData.length} products.`);
console.log(JSON.stringify(productsData, null, 2));

