const tabId = 1962625065;
const accuratePrices = await browserjs(tabId, () => {
  const cards = Array.from(document.querySelectorAll('.product_wrapper, article.product, li.product_wrapper'));

  return cards.map((p, idx) => {
    const titleLink = p.querySelector('a.productClickItemV2[href*="/product/"]:not(.image2)') || p.querySelector('.p-title, h2, a[data-name]');
    const rawTitle = titleLink?.getAttribute('data-name') || titleLink?.textContent.trim() || "";
    const title = rawTitle.replace(/&quot;/g, '"').replace(/&amp;/g, '&');
    const brand = titleLink?.getAttribute('data-brand') || "";

    const sku = p.innerText.match(/SKU:\s*(\d+)/)?.[1] || "";

    // Look for "Our price" specifically
    const cardText = p.innerText;
    const ourPriceMatch = cardText.match(/Our price\s*\$([0-9,]+\.[0-9]{2})/i);
    const regularPriceMatch = cardText.match(/\$([0-9,]+\.[0-9]{2})/);

    let finalPrice = null;
    let finalPriceStr = "";
    if (ourPriceMatch) {
      finalPrice = parseFloat(ourPriceMatch[1].replace(/,/g, ''));
      finalPriceStr = `$${ourPriceMatch[1]}`;
    } else if (regularPriceMatch) {
      finalPrice = parseFloat(regularPriceMatch[1].replace(/,/g, ''));
      finalPriceStr = `$${regularPriceMatch[1]}`;
    } else {
      const favLink = p.querySelector('a.favorite');
      const dataPrice = favLink?.getAttribute('data-price');
      if (dataPrice) {
        finalPrice = parseFloat(dataPrice);
        finalPriceStr = `$${dataPrice} (unlisted on card)`;
      } else {
        finalPriceStr = "Price unlisted";
      }
    }

    return {
      cardIndex: idx + 1,
      brand,
      title,
      price: finalPrice,
      priceFormatted: finalPriceStr,
      sku
    };
  });
});

// Sort by price ascending
const sorted = [...accuratePrices].sort((a, b) => {
  if (a.price === null) return 1;
  if (b.price === null) return -1;
  return a.price - b.price;
});

console.log("Accurate sorted list:");
sorted.forEach((item, i) => {
  console.log(`${i + 1}. [${item.sku}] ${item.title} - ${item.priceFormatted}`);
});

